import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { Ajv2020 } from 'ajv/dist/2020.js';
import { describe, expect, it } from 'vitest';
import { findLeaks, protectedValues, writeSyntheticBundles } from '../../src/evaluation/index.ts';
import { buildUiFixtures, isEntryPoint, main } from '../../src/evaluation/ui-fixtures.ts';
import { readInvestigationResult } from '../../src/index.ts';
import type { UiFixtures } from '../../src/ui/data/types.ts';

/**
 * The console's fixtures (ADR 0011): generated by the real pipeline, committed byte for byte,
 * contract-valid, covering every state, and free of answer-key content and paths.
 */
const FILE = new URL('../../src/ui/fixtures/fixtures.json', import.meta.url);
const committedText = () => readFile(FILE, 'utf8');
const committed = async () => JSON.parse(await committedText()) as UiFixtures;

describe('the console fixtures', () => {
  it('are exactly what the generator produces: regenerate with `pnpm fixtures:ui`', async () => {
    let out = '';
    expect(await main({ write: (t: string) => (out += t) })).toBe(0);
    expect(out).toBe(await committedText());
  });

  it('pass the result contract, in the code and in the published schema', async () => {
    const schema = JSON.parse(
      await readFile(
        new URL(
          '../../docs/contracts/investigation-result/v0/investigation-result.schema.json',
          import.meta.url,
        ),
        'utf8',
      ),
    ) as object;
    const validate = new Ajv2020({ strict: true, allErrors: true }).compile(schema);
    for (const inv of (await committed()).investigations) {
      expect(readInvestigationResult(inv.result).ok, inv.id).toBe(true);
      expect(validate(inv.result), inv.id).toBe(true);
    }
  });

  it('cover every result state and both validation outcomes', async () => {
    const f = await committed();
    const states = f.investigations.map((i) => [i.result.outcome, i.result.caseId === null]);
    expect(states).toEqual(
      expect.arrayContaining([
        ['completed', false],
        ['inconclusive', false],
        ['failed', false],
        ['budget_exceeded', false],
        ['failed', true],
      ]),
    );
    const validations = f.bundles.map((b) => [b.validation.valid, b.validation.issues.length > 0]);
    expect(validations).toEqual(
      expect.arrayContaining([
        [true, false],
        [false, true],
      ]),
    );
    // Each investigation names a fixture bundle.
    const ids = new Set(f.bundles.map((b) => b.id));
    expect(f.investigations.every((i) => ids.has(i.bundleId))).toBe(true);
    expect(new Set(f.bundles.map((b) => b.origin))).toEqual(new Set(['fixture']));
  });

  it('say they are fixtures, and carry no paths, answer file or scenario names', async () => {
    const text = await committedText();
    const f = JSON.parse(text) as UiFixtures;
    expect(f.notice).toMatch(/^Fixture data\./);
    expect(f.notice).toContain('No live investigation ran');
    expect(text).not.toContain(tmpdir());
    expect(text).not.toContain('ground_truth');
    for (const name of ['provider-outage', 'synthetic-cache-saturation', 'excerpt-correct'])
      expect(text, name).not.toContain(name);
  });

  it("contain none of the synthetic bundles' answer text, in any form the leak check knows", async () => {
    const root = await mkdtemp(join(tmpdir(), 'eoai-ui-leak-'));
    try {
      const b = await writeSyntheticBundles(root);
      const values = [
        ...(await protectedValues(b.excerpt)),
        ...(await protectedValues(b.fabricated)),
      ].filter((v) => v.policy === 'always');
      expect(values.length).toBeGreaterThan(10);
      // As in the evaluation harness, the model's own text (findings, remediation, limitations)
      // is not scanned: a correct diagnosis legitimately states the answer. Everything the
      // pipeline and the generator wrote is.
      const f = await committed();
      const written = {
        ...f,
        investigations: f.investigations.map((i) => ({
          ...i,
          result: { ...i.result, findings: [], remediation: [], limitations: [] },
        })),
      };
      const check = findLeaks([{ channel: 'fixtures', text: JSON.stringify(written) }], values, '');
      expect(check.findings).toEqual([]);
    } finally {
      await rm(root, { recursive: true, force: true });
    }
  });

  it('are generated without reading the answer key or scoring anything', async () => {
    const source = await readFile(
      new URL('../../src/evaluation/ui-fixtures.ts', import.meta.url),
      'utf8',
    );
    expect(source).not.toMatch(
      /readAnswerKey|scoreResult|protectedValues|GROUND_TRUTH|ground_truth/,
    );
  });

  it('are deterministic', async () => {
    expect(JSON.stringify(await buildUiFixtures())).toBe(JSON.stringify(await committed()));
  });

  it('know when the generator is the program being run', () => {
    const url = new URL('../../src/evaluation/ui-fixtures.ts', import.meta.url);
    expect(isEntryPoint(url.href, url.pathname)).toBe(true);
    expect(isEntryPoint(url.href, '/elsewhere.ts')).toBe(false);
    expect(isEntryPoint(url.href, undefined)).toBe(false);
  });
});
